allowed = {(r[0], r[1]) for r in rows}
tasks = list({r[0] for r in rows})
workers = list({r[1] for r in rows})
def max_tasks(t_idx, assigned_workers):
    if t_idx == len(tasks):
        return 0
    best = max_tasks(t_idx + 1, assigned_workers)
    for w in workers:
        if w not in assigned_workers and (tasks[t_idx], w) in allowed:
            res = 1 + max_tasks(t_idx + 1, assigned_workers | {w})
            if res > best:
                best = res
    return best
